L44fffe:{if(c->fault||++c->steps>c->limit){fault(c,0x44fffe);return 0;}/* mov eax, dword ptr [ebp + 8] */c->eax=(rd(c,(uint32_t)(0x8u+c->ebp),32));return 0x450001u;}
